def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    rich_threat = 0
    urgent_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 900:
                rich_threat += 1
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev.get('bid', 0.0)))

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    units = supply / float(WATER_REQ)
    scarcity = 0
    if units < 1.6:
        scarcity = 2
    elif units < 2.1:
        scarcity = 1

    my_urgent = 0
    if hp <= 2 or no_water_days >= 1:
        my_urgent = 2
    elif hp <= 4:
        my_urgent = 1

    base = 0.0

    if my_urgent == 2:
        if highest_prev > 0:
            base = max(78.0, highest_prev + 2.0)
        else:
            base = 82.0
        if scarcity == 2:
            base += 8.0
    elif my_urgent == 1:
        if scarcity == 2:
            base = max(58.0, avg_prev + 3.0)
        elif scarcity == 1:
            base = max(46.0, avg_prev * 0.7)
        else:
            base = 34.0
    else:
        if scarcity == 2:
            base = max(28.0, avg_prev * 0.42)
        elif scarcity == 1:
            base = max(20.0, avg_prev * 0.3)
        else:
            base = 12.0

    if rich_threat >= 2 and my_urgent == 0:
        base *= 0.85
    if urgent_opp >= 2 and my_urgent >= 1:
        base += 4.0
    if day >= 8 and hp >= 5 and no_water_days == 0:
        base *= 0.9

    reserve_floor = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    cap = budget
    if budget > reserve_floor:
        cap = max(0.0, budget - reserve_floor * 0.15)

    bid = min(cap, base)
    if my_urgent == 2:
        bid = min(budget, max(bid, 75.0))

    if bid < 0:
        bid = 0.0
    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday's bids from previous_trace for immediate reaction
    prev_bids = []
    for oid, o in alive:
        pt = o.get('previous_trace', {}) or {}
        b = pt.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate how many full water units might be needed from supply
    # (Used only to choose aggression; bidding is about winning share.)
    # Ensure integer indices if any are used later.
    max_units = int(supply // float(WATER_REQ)) if float(WATER_REQ) > 0 else 0

    # Baseline bid: if supply is tight, bid slightly more; if abundant, bid less.
    # With supply 15-25 and WATER_REQ=9, max_units is 1 or 2.
    if max_units <= 1:
        baseline = DAILY_SALARY * 0.62
    else:
        baseline = DAILY_SALARY * 0.48

    # Pressure from opponents: if yesterday bids were high, we must match/beat.
    if prev_bids:
        prev_high = max(prev_bids)
        prev_avg = sum(prev_bids) / float(len(prev_bids))
    else:
        prev_high = 0.0
        prev_avg = baseline

    # If we are in danger, escalate sharply.
    # No-water days increases risk; low hp increases urgency.
    danger = (my_hp <= 2.5) or (my_no_water_days >= 2)

    # Compute target bid.
    # Aim: slightly above the likely high-pressure cluster but not necessarily above absolute max.
    # Use 0.95 of max to avoid overpaying.
    target = baseline
    if prev_bids:
        # If others paid near our salary, we should not underbid.
        if prev_high >= DAILY_SALARY * 0.85:
            target = max(target, DAILY_SALARY * 0.72)
        # If average is high, follow it with a small premium.
        if prev_avg >= DAILY_SALARY * 0.55:
            target = max(target, prev_avg * 1.03)
        # If we must win under tight conditions, bump toward 95% of their max plus small step.
        if max_units <= 1 and prev_high > 0:
            target = max(target, prev_high * 0.95 + 2.0)

    if danger:
        target = max(target, DAILY_SALARY * 0.88)

    # Final clamp to budget and reasonable cap.
    # Keep within [0, budget].
    bid = max(0.0, min(my_budget, target))

    # If budget is extremely low, still bid something to avoid zero-water death spirals.
    if bid <= 0.0 and my_budget > 0.0:
        bid = min(my_budget, DAILY_SALARY * 0.2)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 75.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max(avg_prev * 1.1, 90.0))

    if day_context['supply'] < 18:
        return min(my_status['budget'], avg_prev + 5.0)

    return min(my_status['budget'], max(avg_prev * 0.9, 65.0))
